import { registerRootComponent } from "expo";
import App from "./App";

registerRootComponent(App);

{
  "extends": "expo/tsconfig.base",
  "compilerOptions": {
    "strict": true
  }
}

name: K1W1 Triggered Build

on:
  repository_dispatch:
    types: [k1w1_build]
  workflow_dispatch:
    inputs:
      ref:
        description: "Branch/Ref to build"
        required: false
        default: ""
      profile:
        description: "EAS profile (development | preview | production)"
        required: false
        default: "development"

permissions:
  contents: write

concurrency:
  group: k1w1-triggered-${{ github.repository }}-${{ github.event.client_payload.ref || inputs.ref || github.ref_name }}-${{ github.event.client_payload.profile || inputs.profile || 'development' }}
  cancel-in-progress: false

jobs:
  build:
    name: EAS Build (Android, WAIT)
    runs-on: ubuntu-latest
    env:
      EXPO_TOKEN: ${{ secrets.EXPO_TOKEN }}
      EAS_CLI_VERSION: 16.32.0
      SUPABASE_URL: ${{ secrets.SUPABASE_URL }}
      SUPABASE_SERVICE_ROLE_KEY: ${{ secrets.SUPABASE_SERVICE_ROLE_KEY }}
      JOB_ID: ${{ github.event.client_payload.job_id || '' }}
      CHECKOUT_REF: ${{ github.event.client_payload.ref || inputs.ref || github.ref_name }}
      PROFILE: ${{ github.event.client_payload.profile || inputs.profile || 'development' }}
      TARGET_BRANCH: ${{ github.event.client_payload.target_branch || github.ref_name }}

    steps:
      - name: Validate secrets
        run: |
          set -euo pipefail
          if [ -z "${EXPO_TOKEN:-}" ]; then
            echo "::error::Missing GitHub Secret EXPO_TOKEN"
            exit 1
          fi

      - name: Checkout repository
        uses: actions/checkout@34e114876b0b11c390a56381ad16ebd13914f8d5 # v4.3.1
        with:
          ref: ${{ env.CHECKOUT_REF }}
          fetch-depth: 0

      - name: Detect lockfile (for cache + install strategy)
        id: lockfile
        run: |
          set -euo pipefail
          if [ -f package-lock.json ]; then
            echo "has_lockfile=true" >> "$GITHUB_OUTPUT"
            echo "lockfile_path=package-lock.json" >> "$GITHUB_OUTPUT"
          elif [ -f npm-shrinkwrap.json ]; then
            echo "has_lockfile=true" >> "$GITHUB_OUTPUT"
            echo "lockfile_path=npm-shrinkwrap.json" >> "$GITHUB_OUTPUT"
          elif [ -f yarn.lock ]; then
            echo "has_lockfile=true" >> "$GITHUB_OUTPUT"
            echo "lockfile_path=yarn.lock" >> "$GITHUB_OUTPUT"
          elif [ -f pnpm-lock.yaml ]; then
            echo "has_lockfile=true" >> "$GITHUB_OUTPUT"
            echo "lockfile_path=pnpm-lock.yaml" >> "$GITHUB_OUTPUT"
          else
            echo "has_lockfile=false" >> "$GITHUB_OUTPUT"
            echo "lockfile_path=" >> "$GITHUB_OUTPUT"
          fi

      - name: Setup Node (with cache)
        if: steps.lockfile.outputs.has_lockfile == 'true'
        uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4.4.0
        with:
          node-version: 20
          cache: npm
          cache-dependency-path: ${{ steps.lockfile.outputs.lockfile_path }}

      - name: Setup Node (no cache - lockfile missing)
        if: steps.lockfile.outputs.has_lockfile != 'true'
        uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4.4.0
        with:
          node-version: 20

      - name: Install dependencies (frozen if possible)
        run: |
          set -euo pipefail
          if [ "${{ steps.lockfile.outputs.has_lockfile }}" = "true" ]; then
            echo "Using npm ci (lockfile: ${{ steps.lockfile.outputs.lockfile_path }})"
            npm ci --no-audit --no-fund
          else
            echo "::warning::No lockfile found in repo. Falling back to npm install (non-reproducible)."
            npm install --no-audit --no-fund
          fi

      - name: Clean incomplete native directories (managed build guard)
        run: |
          set -euo pipefail
          if [ -d android ] && [ ! -f android/app/build.gradle ] && [ ! -f android/app/build.gradle.kts ]; then
            echo "::warning::android/ exists but android/app/build.gradle is missing -> removing android/ (and ios/) before EAS build."
            rm -rf android ios || true
          fi
          if [ -d ios ] && [ ! -f ios/Podfile ]; then
            echo "::warning::ios/ exists but ios/Podfile is missing -> removing ios/ before EAS build."
            rm -rf ios || true
          fi

      - name: CI config sanity (eas.json)
        run: |
          set -euo pipefail
          node - <<'NODE'
          const fs = require('fs');
          const path = 'eas.json';
          if (!fs.existsSync(path)) {
            console.log('No eas.json found -> skipping.');
            process.exit(0);
          }
          const eas = JSON.parse(fs.readFileSync(path, 'utf8'));
          eas.cli = eas.cli || {};
          if (!eas.cli.appVersionSource) {
            // avoids future required-field warning
            eas.cli.appVersionSource = "remote";
          }
          eas.build = eas.build || {};
          const profile = process.env.PROFILE || 'development';
          eas.build[profile] = eas.build[profile] || {};
          eas.build[profile].android = eas.build[profile].android || {};
          if (profile !== 'production') {
            // unsigned debug builds don't need Android Keystore on EAS
            eas.build[profile].android.withoutCredentials = true;
          }
          fs.writeFileSync(path, JSON.stringify(eas, null, 2) + '\n');
          console.log(`Updated eas.json for profile=${profile}`);
          NODE

      - name: Self-heal: ensure lockfile (best effort)
        run: |
          set -euo pipefail

          if [ ! -f package-lock.json ]; then
            echo "📌 Generating package-lock.json..."
            npm install --package-lock-only --no-audit --no-fund
          fi

          if git status --porcelain | grep -qE '^( M|\?\?) (package.json|package-lock.json|\.npmrc)$'; then
            echo "✅ Changes detected -> committing back to repo."
            git config user.email "github-actions[bot]@users.noreply.github.com"
            git config user.name "github-actions[bot]"
            git add package.json package-lock.json .npmrc 2>/dev/null || true
            git commit -m "chore(ci): self-heal lockfile" || true
            BR="${TARGET_BRANCH:-}"
            if [ -z "$BR" ]; then BR="$(git rev-parse --abbrev-ref HEAD)"; fi
            echo "🚀 Pushing to origin $BR (best effort)..."
            git push origin "HEAD:$BR" || echo "::warning::Could not push self-heal commit (branch may be protected or ref is not a branch)."
          else
            echo "ℹ️ No relevant changes to commit."
          fi

      - name: Install EAS CLI
        run: |
          set -euo pipefail
          npm i -g eas-cli@${EAS_CLI_VERSION}
          eas --version


- name: Fetch Android keystore (production only)
  if: env.PROFILE == 'production'
  shell: bash
  run: |
    set -euo pipefail
    if [ -z "${SUPABASE_URL:-}" ] || [ -z "${SUPABASE_SERVICE_ROLE_KEY:-}" ]; then
      echo "::error::Missing SUPABASE_URL / SUPABASE_SERVICE_ROLE_KEY secrets."
      exit 1
    fi

    echo "🔐 Fetching Android keystore for ${GITHUB_REPOSITORY}..."
    curl -sS -X POST "${SUPABASE_URL}/functions/v1/android-keystore-export" \
      -H "Authorization: Bearer ${SUPABASE_SERVICE_ROLE_KEY}" \
      -H "Content-Type: application/json" \
      --data "{"repo":"${GITHUB_REPOSITORY}","mode":"production"}" \
      -o keystore_export.json

    node <<'NODE'
    const fs = require('fs');
    const path = require('path');

    const raw = fs.readFileSync('keystore_export.json', 'utf8');
    let obj;
    try { obj = JSON.parse(raw); } catch (e) {
      console.error('::error::Invalid JSON from android-keystore-export');
      console.error(raw);
      process.exit(1);
    }

    if (!obj.ok) {
      console.error('::error::Keystore export failed: ' + (obj.error || 'unknown'));
      console.error(raw);
      process.exit(1);
    }

    fs.mkdirSync('android', { recursive: true });
    const jksPath = path.join('android', obj.keystorePath || 'keystore.jks');
    fs.writeFileSync(jksPath, Buffer.from(obj.keystoreBase64, 'base64'));

    const credentials = {
      android: {
        keystore: {
          keystorePath: jksPath,
          keystorePassword: obj.keystorePassword,
          keyAlias: obj.keyAlias,
          keyPassword: obj.keyPassword,
        }
      }
    };
    fs.writeFileSync('credentials.json', JSON.stringify(credentials, null, 2) + '\n');
    console.log('✅ Wrote android/' + path.basename(jksPath) + ' + credentials.json');
    NODE

    rm -f keystore_export.json


- name: Inject Android Keystore (production)
  if: env.PROFILE == 'production'
  run: |
    set -euo pipefail
    echo "🔐 Injecting Android keystore + credentials.json (production)..."

    if [ -z "${SUPABASE_URL:-}" ] || [ -z "${SUPABASE_SERVICE_ROLE_KEY:-}" ]; then
      echo "::error::Missing SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY"
      exit 1
    fi

    # Ensure jq exists (GitHub hosted runners usually have it, but be safe)
    if ! command -v jq >/dev/null 2>&1; then
      echo "Installing jq..."
      sudo apt-get update -y
      sudo apt-get install -y jq
    fi

    # Enforce local credentials for production (avoid EAS trying to generate remote keystore)
    node - <<'NODE'
    const fs = require('fs');
    const path = 'eas.json';
    const j = JSON.parse(fs.readFileSync(path, 'utf8'));
    j.build = j.build || {};
    j.build.production = j.build.production || {};
    j.build.production.android = j.build.production.android || {};
    j.build.production.android.credentialsSource = 'local';
    fs.writeFileSync(path, JSON.stringify(j, null, 2) + "\n");
    console.log("✅ Ensured eas.json: build.production.android.credentialsSource=local");
    NODE

    REPO="${GITHUB_REPOSITORY}"
    echo "Repo: ${REPO}"

    RESP="$(curl -sS -X POST "${SUPABASE_URL}/functions/v1/android-keystore-export" \
      -H "Authorization: Bearer ${SUPABASE_SERVICE_ROLE_KEY}" \
      -H "Content-Type: application/json" \
      -d "{"repo":"${REPO}"}")"

    echo "${RESP}" | jq -e '.ok == true' >/dev/null || {
      echo "${RESP}"
      echo "::error::android-keystore-export failed. Generate keystore in a0style first (CredentialsWizard)."
      exit 1
    }

    mkdir -p android
    echo "${RESP}" | jq -r '.keystoreBase64' | base64 -d > android/keystore.jks

    KS_PASS="$(echo "${RESP}" | jq -r '.keystorePassword')"
    KEY_ALIAS="$(echo "${RESP}" | jq -r '.keyAlias')"
    KEY_PASS="$(echo "${RESP}" | jq -r '.keyPassword')"

    cat > credentials.json <<EOF
    {
      "android": {
        "keystore": {
          "keystorePath": "android/keystore.jks",
          "keystorePassword": "${KS_PASS}",
          "keyAlias": "${KEY_ALIAS}",
          "keyPassword": "${KEY_PASS}"
        }
      }
    }
    EOF

    echo "✅ Wrote android/keystore.jks + credentials.json"

- name: Run EAS Build (WAIT)
        id: eas
        run: |
          set -euo pipefail
          echo "🚀 Starting EAS build (android, profile=${PROFILE}) with --wait..."
          BUILD_OUTPUT="$(eas build --platform android --profile "${PROFILE}" --non-interactive --wait 2>&1)" || {
            CODE=$?
            echo "${BUILD_OUTPUT}"
            echo "::error::EAS build failed (exit ${CODE})"
            exit "${CODE}"
          }

          echo "${BUILD_OUTPUT}"

          BUILD_ID="$(echo "${BUILD_OUTPUT}" | grep -oE "Build ID:[[:space:]]*[a-fA-F0-9-]+" | head -n1 | awk '{print $3}' || true)"
          if [ -z "${BUILD_ID}" ]; then BUILD_ID="unknown"; fi
          echo "build_id=${BUILD_ID}" >> "${GITHUB_OUTPUT}"

          BUILD_URL="$(echo "${BUILD_OUTPUT}" | grep -oE "https?://[^[:space:]]+" | grep -E "/projects/[^/]+/builds/[a-fA-F0-9-]+" | head -n1 || true)"
          echo "build_url=${BUILD_URL}" >> "${GITHUB_OUTPUT}"

      - name: Summary
        if: always()
        run: |
          cat >> "$GITHUB_STEP_SUMMARY" << EOF
          ## Triggered Build Summary

          - Repo: ${{ github.repository }}
          - Event: ${{ github.event_name }}
          - Checkout ref: ${CHECKOUT_REF}
          - Profile: ${PROFILE}
          - Commit: $(git rev-parse HEAD)
          - Lockfile present: ${{ steps.lockfile.outputs.has_lockfile }}
          - Lockfile path: ${{ steps.lockfile.outputs.lockfile_path }}
          - EAS CLI: $(eas --version 2>/dev/null || echo "unknown")
          - Build ID: ${{ steps.eas.outputs.build_id }}
          - Build URL: ${{ steps.eas.outputs.build_url }}
          EOF

{
  "cli": {
    "version": "16.0.0",
    "appVersionSource": "remote"
  },
  "build": {
    "development": {
      "developmentClient": true,
      "distribution": "internal",
      "android": {
        "buildType": "apk",
        "gradleCommand": ":app:assembleDebug",
        "withoutCredentials": true
      },
      "env": {
        "NODE_ENV": "development",
        "APP_VARIANT": "development"
      }
    },
    "preview": {
      "android": {
        "buildType": "apk",
        "withoutCredentials": true
      },
      "env": {
        "NODE_ENV": "production",
        "APP_VARIANT": "preview"
      }
    },
    "production": {
      "android": {
        "buildType": "apk",
        "credentialsSource": "local"
      },
      "env": {
        "NODE_ENV": "production",
        "PRECHECK": "true",
        "APP_VARIANT": "production"
      }
    }
  }
}

// eslint.config.js (Flat Config)
// Expo flat config + GLOBAL ignores + Projekt-spezifische Rules

// https://docs.expo.dev/guides/using-eslint/
const expoConfig = require('eslint-config-expo/flat');

module.exports = [
  // ✅ WICHTIG: Global ignores müssen VOR expoConfig kommen,
  // sonst greifen Expo-Regeln bereits auf die Dateien.
  {
    ignores: [
      'node_modules/**',
      'backups/**',
      '.expo/**',
      '.expo-shared/**',
      'dist/**',
      'build/**',
      '__mocks__/**',
      '**/*.test.*',
      'jest.setup.js',
      'supabase/functions/**',
      'web-build/**',
      'android/**',
      'ios/**',
    ],
  },

  ...expoConfig,

  // Projekt-spezifische Lockerungen
  {
    rules: {
      // Import-Kram entspannen
      'import/no-unresolved': 'off',
      'import/no-duplicates': 'off',
      'import/no-named-as-default': 'off',
      'import/no-named-as-default-member': 'off',

      // TS-Style-Regeln, die aktuell nur nerven
      '@typescript-eslint/array-type': 'off',
      '@typescript-eslint/no-require-imports': 'off',
      '@typescript-eslint/no-unused-vars': 'off',

      // Hooks-Warnungen abschalten (Code läuft ja)
      'react-hooks/exhaustive-deps': 'off',
    },
  },
];

/* eslint-env jest */
import "react-native-gesture-handler/jestSetup";

jest.mock("react-native-reanimated", () =>
  require("react-native-reanimated/mock"),
);

jest.mock("react-native/Libraries/Animated/NativeAnimatedHelper", () => ({}), {
  virtual: true,
});

// Wichtig: Kein Factory-Require, damit __mocks__/expo-secure-store.js genutzt wird
jest.mock("expo-secure-store");

jest.mock("uuid", () => ({ v4: () => "test-uuid" }));

// 🔥 react-native-webview in Tests immer mocken
jest.mock("react-native-webview");

// ✅ Fix: expo-notifications side effects in Jest verhindern (Worker-Leaks / Warnspam)
jest.mock("expo-notifications", () => ({
  // permissions
  getPermissionsAsync: jest.fn(async () => ({ status: "granted" })),
  requestPermissionsAsync: jest.fn(async () => ({ status: "granted" })),

  // token
  getExpoPushTokenAsync: jest.fn(async () => ({
    data: "ExponentPushToken[test-token]",
  })),

  // handler / channels
  setNotificationHandler: jest.fn(),
  setNotificationChannelAsync: jest.fn(async () => ({})),

  // scheduling / clearing
  scheduleNotificationAsync: jest.fn(async () => "notification-id"),
  cancelAllScheduledNotificationsAsync: jest.fn(async () => {}),
  dismissAllNotificationsAsync: jest.fn(async () => {}),
  // listeners: wichtig => Rückgabeobjekt mit remove()
  addNotificationReceivedListener: jest.fn(() => ({ remove: jest.fn() })),
  addNotificationResponseReceivedListener: jest.fn(() => ({
    remove: jest.fn(),
  })),
  removeNotificationSubscription: jest.fn(),

  // constants
  AndroidImportance: { MAX: 5 },
}));

// Android-only Expo config with build-profile variant support.
    // Variant is driven via eas.json -> build.<profile>.env.APP_VARIANT.
    const baseExpo = {
  "name": "Expo SDK54 Base",
  "slug": "expo-sdk54-base",
  "version": "1.0.0",
  "orientation": "portrait",
  "icon": "./assets/icon.png",
  "userInterfaceStyle": "automatic",
  "splash": {
    "image": "./assets/splash.png",
    "resizeMode": "contain",
    "backgroundColor": "#ffffff"
  },
  "assetBundlePatterns": [
    "**/*"
  ],
  "android": {
    "adaptiveIcon": {
      "foregroundImage": "./assets/adaptive-icon.png",
      "backgroundColor": "#ffffff"
    },
    "package": "com.yourcompany.exposdk54base"
  },
  "web": {
    "favicon": "./assets/favicon.png"
  },
  "platforms": [
    "android"
  ],
  "newArchEnabled": true
};

    const getVariant = () => {
      const v =
        process.env.APP_VARIANT ||
        process.env.BUILD_PROFILE ||
        process.env.EAS_BUILD_PROFILE ||
        "preview";
      return String(v).toLowerCase();
    };

    module.exports = ({ config }) => {
      const variant = getVariant();
      const isDev = variant === "development";

      return {
        expo: {
          ...baseExpo,
          // Keep anything Expo injects (rare in our case), but never enable unsupported platforms.
          ...(config?.expo || {}),
          platforms: ["android"],
          updates: {
            ...(baseExpo.updates || {}),
            ...((config?.expo || {}).updates || {}),
            enabled: !isDev,
          },
          extra: {
            ...(baseExpo.extra || {}),
            ...((config?.expo || {}).extra || {}),
            appVariant: variant,
          },
        },
      };
    };
